def run(nextFunc):
    while True:
        nextFunc = nextFunc()

def storeWelcome():
    time.sleep(1)
    print("\nWelcome to the pony challenge store. What would you like to do?")
    print("1. Buy")
    print("2. Sell")
    print("3. Examine")
    print("4. Threaten")
    print("5. Restock")
    print("6. Leave")
    choice = input()
    if(choice == "1"):
        return storeBuy
    elif(choice == "2"):
        return storeSell
    elif(choice == "3"):
        return storeExamine
    elif(choice == "4"):
        return storeThreaten
    elif(choice == "5"):
        return storeRestock
    elif(choice == "6"):
        return storeLeave
    else:
        return storeWelcome
storeLeave = lambda: [print("Goodbye"), exit()]

money = 1<<24
randomize = lambda x: (x*0x1337)%(1<<32)
randomize2 = lambda x: (x&0xF)<<4|(x&0xF0)<<4|(x&0xF00)>>8|x&~0xFFF
randomize3 = lambda x: x^24^1^73^5
items = []
def storeBuy():
    global money
    print("What would you like to buy?")
    print("{:20}| {}".format("Item", "Price"))
    for k in stock:
        print("{:20}| {}".format(k,stock[k]))
    choice = input()
    if(choice not in stock):
        print("Sorry, that item is not in stock.")
    elif(stock[choice] > money):
        print("Sorry, you don't have enough money")
    else:
        print("You bought a {} for ${}.".format(choice, stock[choice]))
        items.append(choice)
        money -= stock[choice]
    return storeWelcome

def storeExamine():
    print("What would you like to examine?")
    print("1. Store")
    print("2. Items")
    print("3. Money")
    print("4. Outside")
    print("5. Flag")
    choice = input()
    if(choice == "1"):
        print("The store is actually just a cardboard box.")
    elif(choice == "2"):
        print("Your items: " + str(items))
    elif(choice == "3"):
        print("You have $"+str(money))
    elif(choice == "4"):
        print("An empty void.")
    elif(choice == "5"):
        print("Stores don't have flags, do they? Maybe if it was a flag store, but this one isn't.")
        if("rev 1" not in items):
            print("Maybe this store can start selling flags if you say some magic words.")
            words = list(input().encode())
            c = 0x2cfe5124
            while(c != 60):
                words = [randomize3(randomize2(randomize3(x))) for x in words]
                c = randomize(c)
            if(words == data):
                print("Oh, looks like you already have the flag. No need for magic then :)")
                exit()
            print("Nothing happened...")
    else:
        print("Examining the invalid option and reveals that it is invalid.")
    return storeWelcome

stock = {"Nothing": 1}
totalDays = 0
def storeRestock():
    global totalDays, stock
    totalDays += random.randint(1, 100)
    random.seed(totalDays)
    stock = {}
    for _ in range(10):
        type = random.randint(0, 120)
        id = random.randint(0,10)
        if(type < 10):
            stock["rev "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 20):
            stock["pwn "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 30):
            stock["web "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 40):
            stock["crypto "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 50):
            stock["network "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 60):
            stock["forensics "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 70):
            stock["shell "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 80):
            stock["jail "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 90):
            stock["osint "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
        elif(type < 100):
            stock["misc "+str(randomize(data[type+id]))] = randomize(random.randint(500,2000))
    print("The store has been restocked")
    return storeWelcome

def storeSell():
    print("Sorry, we don't buy gold here (or challenges, for that matter).")
    return storeWelcome

def storeThreaten():
    i = randomize(data[random.randint(0, 100)])
    print(["That's not very nice :(", "Yikes"][i%3%2])
    return storeWelcome

if(__name__ == "__main__"):
    run(storeWelcome)
